use bhoo::*;
use bhoo::android_xml::{LayoutState,Visibility};
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_tab_host.rs"));}
const B:Rect=Rect{x:0.,y:0.,width:300.,height:220.};
fn draw(ui:&mut Ui,s:&mut LayoutState,input:Input){ui.frame(input,B,0.,|f|{fixture::LAYOUT.render(f,B,s);});}
fn touch(x:f32,pressed:bool,released:bool,time:f64)->Input{Input{pointer:Some([x,28.]),pointer_kind:PointerKind::Touch,pressed,released,time,..Input::default()}}
fn setup()->(Ui,LayoutState){let mut s=LayoutState::default();s.configure_tab_host("tabhost","android:tabs",vec!["page_one".into(),"page_two".into(),"page_three".into()]).unwrap();(Ui::default(),s)}
#[test] fn selecting_tabs_switches_content(){let(mut ui,mut s)=setup();draw(&mut ui,&mut s,Input::default());assert_eq!(s.visibility["page_one"],Visibility::Visible);assert_eq!(s.visibility["page_two"],Visibility::Gone);draw(&mut ui,&mut s,touch(150.,true,false,1.));draw(&mut ui,&mut s,touch(150.,false,true,1.1));assert_eq!(s.tab_hosts["tabhost"].selected,1);assert_eq!(s.visibility["page_one"],Visibility::Gone);assert_eq!(s.visibility["page_two"],Visibility::Visible);}
#[test] fn programmatic_selection_validates_index(){let(mut ui,mut s)=setup();assert!(s.set_tab_host_current("tabhost",2));assert!(!s.set_tab_host_current("tabhost",3));draw(&mut ui,&mut s,Input::default());assert_eq!(s.visibility["page_three"],Visibility::Visible);assert_eq!(s.displayed_children["android:tabs"],2);}
#[test] fn duplicate_content_ids_are_rejected(){let mut s=LayoutState::default();assert!(s.configure_tab_host("host","tabs",vec!["same".into(),"same".into()]).is_err());}
mod dynamic {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_tab_host_dynamic.rs"));}
#[test] fn generated_label_tabs_switch_content_and_tag_selection(){let mut s=LayoutState::default();s.configure_tab_host_labels("tabhost","android:tabs",vec![("one".into(),"First".into(),"page_one".into()),("two".into(),"Second".into(),"page_two".into()),("three".into(),"Third".into(),"page_three".into())]).unwrap();let mut ui=Ui::default();ui.frame(touch(150.,true,false,1.),B,0.,|f|{dynamic::LAYOUT.render(f,B,&mut s);});ui.frame(touch(150.,false,true,1.1),B,0.,|f|{dynamic::LAYOUT.render(f,B,&mut s);});assert_eq!(s.tab_hosts["tabhost"].selected,1);assert_eq!(s.visibility["page_two"],Visibility::Visible);assert!(s.set_tab_host_by_tag("tabhost","three"));assert!(!s.set_tab_host_by_tag("tabhost","missing"));assert_eq!(s.visibility["page_three"],Visibility::Visible);}
mod factory_layout {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_tab_host_factory.rs"));}
mod factory_first {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_tab_host_factory_first.rs"));}
mod factory_second {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_tab_host_factory_second.rs"));}
fn factory(tag:&str)-> &'static android_xml::Node {if tag=="one"{&factory_first::LAYOUT}else{&factory_second::LAYOUT}}
#[test] fn factory_content_is_created_lazily_and_reused(){let mut s=LayoutState::default();s.configure_tab_host_factory("tabhost","android:tabs",vec![("one".into(),"First".into()),("two".into(),"Second".into())],factory).unwrap();let mut ui=Ui::default();assert_eq!(s.tab_host_created_count("tabhost"),0);ui.frame(Input::default(),B,0.,|f|{factory_layout::LAYOUT.render(f,B,&mut s);});assert_eq!(s.tab_host_created_count("tabhost"),1);ui.frame(touch(225.,true,false,1.),B,0.,|f|{factory_layout::LAYOUT.render(f,B,&mut s);});ui.frame(touch(225.,false,true,1.1),B,0.,|f|{factory_layout::LAYOUT.render(f,B,&mut s);});assert_eq!(s.tab_hosts["tabhost"].selected,1);assert_eq!(s.tab_host_created_count("tabhost"),2);s.set_tab_host_by_tag("tabhost","one");ui.frame(Input{time:2.,..Input::default()},B,0.,|f|{factory_layout::LAYOUT.render(f,B,&mut s);});assert_eq!(s.tab_host_created_count("tabhost"),2);s.configure_tab_host_factory("tabhost","android:tabs",vec![("one".into(),"First".into())],factory).unwrap();assert_eq!(s.tab_host_created_count("tabhost"),0);}
#[test] fn factory_content_has_visible_size(){let mut s=LayoutState::default();s.configure_tab_host_factory("tabhost","android:tabs",vec![("one".into(),"First".into())],factory).unwrap();let mut ui=Ui::default();let commands=ui.frame(Input::default(),B,0.,|f|{factory_layout::LAYOUT.render(f,B,&mut s);});assert!(commands.iter().any(|cmd|matches!(cmd,DrawCommand::Text{text,bounds,..} if text.as_ref()=="First factory content" && bounds.height>0.0)));}
mod mixed {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_tab_host_mixed.rs"));}
#[test] fn mixed_view_and_factory_switch_and_reuse(){use bhoo::android_xml::TabHostContent;let mut s=LayoutState::default();s.configure_tab_host_mixed("tabhost","android:tabs",vec![("one".into(),"First".into(),TabHostContent::View("page_one".into())),("two".into(),"Second".into(),TabHostContent::Factory(factory))]).unwrap();let mut ui=Ui::default();let commands=ui.frame(Input::default(),B,0.,|f|{mixed::LAYOUT.render(f,B,&mut s);});assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="First XML content")));assert_eq!(s.tab_host_created_count("tabhost"),0);s.set_tab_host_by_tag("tabhost","two");let commands=ui.frame(Input{time:1.,..Input::default()},B,0.,|f|{mixed::LAYOUT.render(f,B,&mut s);});assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="Second factory content")));assert!(!commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="First XML content")));assert_eq!(s.tab_host_created_count("tabhost"),1);s.set_tab_host_by_tag("tabhost","one");ui.frame(Input{time:2.,..Input::default()},B,0.,|f|{mixed::LAYOUT.render(f,B,&mut s);});s.set_tab_host_by_tag("tabhost","two");ui.frame(Input{time:3.,..Input::default()},B,0.,|f|{mixed::LAYOUT.render(f,B,&mut s);});assert_eq!(s.tab_host_created_count("tabhost"),1);}
